head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > oncellclick]<br/>GridView 컴포넌트의 Body 영역을 Cell 을 마우스 왼쪽 버튼으로 클릭할 때 발생합니다.",
    "validation" : [
        "Body 영역의 Cell 을 마우스 왼쪽 버튼으로 클릭할 때 oncellclick 이벤트가 발생해야 합니다.",
        "rowIndex 파라미터로 클릭된 Cell 의 Row 인덱스값이 전달되어야 합니다.",
        "columnIndex 파라미터로 클릭된 Cell 의 Column 인덱스값이 전달되어야 합니다.",
        "columnId 파라미터로 클릭된 Cell 의 Column ID 값이 전달되어야 합니다.",
        "ignoreReadOnlyCellClick=true 인 경우 읽기 전용(readonly) 상태의 Cell 을 클릭해도 oncellclick 이벤트가 발생하지 않아야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        ignoreReadOnlyCellClick: con_ignoreReadOnlyCellClick.getText(),
        readOnlyBackgroundColor: "#D3D3D3",
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["oncellclick"]);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);

    // Column 1 readOnly 설정
    target1.setColumnReadOnly(1, true);
}



scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oncellclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("rowIndex : " + rowIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("columnIndex : " + columnIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("columnId : " + columnId);
}
